import { PaymentServicesSDK } from '@adobe-commerce/payment-services-sdk';
import { activeCreditCardForm, CreditCardFormHandle } from './creditCardForm';
import { state } from './state';

/**
 * Finalize Payment Services drop-in initialization with "ready" status.
 */
export function initializationSucceeded(paymentsSDK: {
  checkout: PaymentServicesSDK
  productDetail: PaymentServicesSDK
}) {
  state.value = { paymentsSDK, status: 'ready' };
}

/**
 * Finalize Payment Services drop-in initialization with "error" status.
 */
export function initializationFailed() {
  state.value = { paymentsSDK: null, status: 'error' };
}

/**
 * Register the currently-rendered CreditCard form ref in global dropin state.
 * At most one CreditCard container is expected per page.
 */
export function creditCardFormMounted(handle: CreditCardFormHandle) {
  if (activeCreditCardForm.current) {
    console.warn(
      'A CreditCard form is already registered; replacing it. Only one CreditCard is supported per page.'
    );
  }
  activeCreditCardForm.current = handle;
}

/**
 * Unregister the CreditCard form ref when the CreditCard container unmounts.
 * Only clears it when `ref` is still the active one, so a form unmounting after
 * a newer one registered does not wipe the newer ref.
 */
export function creditCardFormUnmounted(ref: CreditCardFormHandle) {
  if (activeCreditCardForm.current === ref) {
    activeCreditCardForm.current = null;
  }
}
