import { PaymentServicesError } from "@/lib/error";
import { RefObject } from "preact/compat";

/** Global ref to the currently rendered credit card form. */
export const activeCreditCardForm: RefObject<CreditCardFormHandle> = {
  current: null,
}

/** Publicly exposed imperative handle to credit card form. */
export interface CreditCardFormHandle {
  /**
   * Returns true only if all credit card form inputs are valid, and focuses the first
   * input that is invalid, if any.
   */
  validate: () => boolean;
  /**
   * Use this method to submit the credit card form and initiate the payment flow.
   */
  submit: () => Promise<void>;
}

declare module "@/lib/error" {
  interface PaymentServicesErrorCode {
    "payment-services/credit-card-form-invalid": void
    "payment-services/credit-card-form-not-rendered": void
  }
}

export class InvalidCreditCardFormError extends PaymentServicesError {
  constructor() {
    super("Cannot submit invalid credit card form.", {
      code: "payment-services/credit-card-form-invalid",
    });
  }
}

export class CreditCardFormNotRendered extends PaymentServicesError {
  constructor() {
    super("Cannot submit non-rendered credit card form.", {
      code: "payment-services/credit-card-form-not-rendered",
    });
  }
}
