/**
 * Awaitable 'sleep'.
 */
export function timeout(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Converts SCREAMING_SNAKE_CASE to kebab-case.
 */
export function screamingSnakeToKebabCase(screamCaseText: string) {
  return screamCaseText.toLowerCase().replace('_', '-');
}

/** Maps an optional value or returns undefined if the value is undefined. */
export function mapOptional<T, R>(value: T | undefined, mapper: (v: T) => R): R | undefined {
  return value === undefined ? undefined : mapper(value)
}

/**
 * Generates a short random alphanumeric string (0-9, a-z), useful for building unique DOM
 * element ids.
 */
export function randomAlphanumericSuffix(length = 9): string {
  const BASE_36 = 36;
  // Math.random().toString(BASE_36) always starts with "0.", so skip it.
  const RADIX_PREFIX_LENGTH = 2;
  return Math.random()
    .toString(BASE_36)
    .slice(RADIX_PREFIX_LENGTH, RADIX_PREFIX_LENGTH + length);
}
